set -eu
cat > /srv/legacy2/numeric-record-ordering/bin/merge <<'ANTRIEB_MERGE_EOF'
#!/bin/sh
set -eu

base=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
output=$base/merged.csv

if [ "$#" -eq 0 ]; then
    set -- "$base"/exports/*.csv
fi

for input do
    if [ ! -f "$input" ] || [ ! -r "$input" ] || [ ! -s "$input" ]; then
        printf 'merge: input is not a readable, non-empty file: %s\n' "$input" >&2
        exit 1
    fi
done

work=$(mktemp -d "$base/.merge.XXXXXX")
trap 'rm -r -- "$work"' EXIT HUP INT TERM
header_file=$work/header
records_file=$work/records
candidate=$work/merged.csv

awk -v header_file="$header_file" -v records_file="$records_file" '
function transaction_id(line,    i, c, nextc, value, comma) {
    if (substr(line, 1, 1) == "\"") {
        value = ""
        i = 2
        while (i <= length(line)) {
            c = substr(line, i, 1)
            if (c == "\"") {
                nextc = substr(line, i + 1, 1)
                if (nextc == "\"") {
                    value = value "\""
                    i += 2
                    continue
                }
                if (nextc == ",") {
                    parsed_id = value
                    return 1
                }
                return 0
            }
            value = value c
            i++
        }
        return 0
    }

    comma = index(line, ",")
    if (comma < 2)
        return 0
    parsed_id = substr(line, 1, comma - 1)
    return 1
}

{
    sub(/\r$/, "")
}

FNR == 1 {
    if (!have_header) {
        header = $0
        print header > header_file
        have_header = 1
        if (substr(header, 1, 15) != "transaction_id,") {
            printf "merge: unexpected header in %s: %s\n", FILENAME, header > "/dev/stderr"
            failed = 1
        }
    } else if ($0 != header) {
        printf "merge: header conflict in %s\n  expected: %s\n  found:    %s\n", FILENAME, header, $0 > "/dev/stderr"
        failed = 1
    }
    next
}

{
    if (!transaction_id($0) || parsed_id !~ /^[0-9]+$/) {
        printf "merge: invalid numeric transaction_id at %s:%d: %s\n", FILENAME, FNR, $0 > "/dev/stderr"
        failed = 1
        next
    }

    normalized = parsed_id
    sub(/^0+/, "", normalized)
    if (normalized == "")
        normalized = "0"

    if (normalized in seen) {
        if (seen[normalized] != $0) {
            printf "merge: conflicting duplicate transaction_id %s\n  first (%s): %s\n  next  (%s:%d): %s\n", parsed_id, location[normalized], seen[normalized], FILENAME, FNR, $0 > "/dev/stderr"
            failed = 1
        }
        next
    }

    seen[normalized] = $0
    location[normalized] = FILENAME ":" FNR
    print normalized "\t" $0 > records_file
}

END {
    if (!have_header) {
        print "merge: no CSV header found" > "/dev/stderr"
        failed = 1
    }
    if (failed)
        exit 1
}
' "$@"

tab=$(printf '\t')
{
    cat "$header_file"
    LC_ALL=C sort -t "$tab" -k1,1n "$records_file" | cut -f2-
} > "$candidate"

if [ -e "$output" ]; then
    chmod "$(stat -c '%a' "$output")" "$candidate"
else
    chmod 0644 "$candidate"
fi
mv -f -- "$candidate" "$output"
printf 'merge: published %s\n' "$output" >&2
ANTRIEB_MERGE_EOF
chmod 0755 /srv/legacy2/numeric-record-ordering/bin/merge
sed -n '1,260p' /srv/legacy2/numeric-record-ordering/bin/merge
sh -n /srv/legacy2/numeric-record-ordering/bin/merge

